import Cocoa
final class SearchController:NSWindowController,NSWindowDelegate,NSTableViewDataSource {
 let root:String;let factory:()throws->RemoteFileClient;let query=NSTextField();let table=NSTableView();let message=NSTextField(labelWithString:"输入名称或通配符，例如 *.csv、report?");var onLocate:((SearchHit)->Void)?;var onClosed:(()->Void)?;private var hits=[SearchHit](),warnings=[String]();private var cancellation:SearchCancellation?;private var busy=false
 var isSearching:Bool{busy}
 init(root:String,factory:@escaping()throws->RemoteFileClient){self.root=root;self.factory=factory;let window=NSWindow(contentRect:NSRect(x:0,y:0,width:850,height:560),styleMask:[.titled,.closable,.miniaturizable,.resizable],backing:.buffered,defer:false);window.isReleasedWhenClosed=false;super.init(window:window);window.title="查找远程文件";window.delegate=self;window.center();window.minSize=NSSize(width:650,height:400)
 let stack=NSStackView();stack.orientation = .vertical;stack.spacing=8;stack.edgeInsets=NSEdgeInsets(top:10,left:10,bottom:10,right:10);stack.translatesAutoresizingMaskIntoConstraints=false;window.contentView!.addSubview(stack);NSLayoutConstraint.activate([stack.leadingAnchor.constraint(equalTo:window.contentView!.leadingAnchor),stack.trailingAnchor.constraint(equalTo:window.contentView!.trailingAnchor),stack.topAnchor.constraint(equalTo:window.contentView!.topAnchor),stack.bottomAnchor.constraint(equalTo:window.contentView!.bottomAnchor)])
 let path=NSTextField(labelWithString:root);path.lineBreakMode = .byTruncatingMiddle;stack.addArrangedSubview(path);path.widthAnchor.constraint(equalTo:stack.widthAnchor,constant:-20).isActive=true;let bar=NSStackView();query.placeholderString="文件名 / 通配符";query.target=self;query.action = #selector(start);query.widthAnchor.constraint(greaterThanOrEqualToConstant:280).isActive=true;bar.addArrangedSubview(query);for(title,action) in [("开始查找",#selector(start)),("取消",#selector(cancel)),("定位选中项",#selector(locate)),("查看警告",#selector(showWarnings))]{bar.addArrangedSubview(NSButton(title:title,target:self,action:action))};stack.addArrangedSubview(bar)
 for(id,title,width) in [("path","完整路径",650.0),("size","大小",120.0)]{let col=NSTableColumn(identifier:.init(id));col.title=title;col.width=width;table.addTableColumn(col)};table.dataSource=self;table.target=self;table.doubleAction = #selector(locate);table.rowHeight=24;let scroll=NSScrollView();scroll.documentView=table;scroll.hasVerticalScroller=true;scroll.hasHorizontalScroller=true;stack.addArrangedSubview(scroll);scroll.widthAnchor.constraint(equalTo:stack.widthAnchor,constant:-20).isActive=true;scroll.heightAnchor.constraint(greaterThanOrEqualToConstant:220).isActive=true;message.lineBreakMode = .byTruncatingMiddle;stack.addArrangedSubview(message);message.widthAnchor.constraint(equalTo:stack.widthAnchor,constant:-20).isActive=true;window.initialFirstResponder=query
 }
 required init?(coder:NSCoder){fatalError()}
 func numberOfRows(in tableView:NSTableView)->Int{hits.count}
 func tableView(_ tableView:NSTableView,objectValueFor tableColumn:NSTableColumn?,row:Int)->Any?{let hit=hits[row];return tableColumn?.identifier.rawValue=="path" ? (hit.directory ? "📁 " : "📄 ")+hit.path : ByteCountFormatter.string(fromByteCount:Int64(clamping:hit.size),countStyle:.file)}
 @objc func start(){guard !busy else{return};let value=query.stringValue;do{_ = try RemoteSearch.pattern(value)}catch{message.stringValue=error.localizedDescription;return};busy=true;query.isEnabled=false;hits=[];warnings=[];table.reloadData();let token=SearchCancellation();cancellation=token;message.stringValue="查找中…";DispatchQueue.global().async{do{let c=try self.factory();defer{token.setInterrupt(nil);c.close()};token.setInterrupt{c.interrupt()};c.checkpoint={try token.check()};var lastReport=Date.distantPast;let results=try RemoteSearch.find(root:self.root,query:value,client:c,cancellation:token,progress:{count,path in guard Date().timeIntervalSince(lastReport)>0.15 else{return};lastReport=Date();DispatchQueue.main.async{self.message.stringValue="已扫描 \(count) 项 · \(path)"}});DispatchQueue.main.async{self.hits=results.hits;self.warnings=results.warnings;self.finish();self.message.stringValue="找到 \(results.hits.count) 项 · 扫描 \(results.scanned) 项 · \(results.warnings.count) 条警告"+(results.truncated ? " · 达到限制，请缩小查找范围" : "");self.table.reloadData()}}catch{DispatchQueue.main.async{self.finish();self.message.stringValue=error.localizedDescription}}}}
 private func finish(){busy=false;query.isEnabled=true;cancellation=nil}
 @objc func cancel(){cancellation?.cancel();message.stringValue="正在取消查找…"}
 @objc func locate(){guard hits.indices.contains(table.selectedRow) else{return};onLocate?(hits[table.selectedRow])}
 @objc func showWarnings(){let a=NSAlert();a.messageText=warnings.isEmpty ? "没有查找警告" : "未能读取的目录";a.informativeText=warnings.prefix(50).joined(separator:"\n");a.runModal()}
 func windowWillClose(_ notification:Notification){cancellation?.cancel();onClosed?()}
}
